def _check_pool_window_ties(pool, inp):
    """扫描 MaxPool2D 对 inp 的全部有效窗口，任一窗口并列最大即抛 ValueError。

    窗口/步长/补边规则与 MaxPool2D.forward 完全一致（补边位置不参与比较）：
    窗口内同一最大值出现两次及以上即视为并列。inp 须为池化层合法四维输入。
    """
    k = pool._kernel_size
    s = pool._stride
    p = pool._padding
    n_ = len(inp)
    c_ = len(inp[0])
    h_ = len(inp[0][0])
    w_ = len(inp[0][0][0])
    oh_ = (h_ + 2 * p - k) // s + 1
    ow_ = (w_ + 2 * p - k) // s + 1
    for n in range(n_):
        x_n = inp[n]
        for c in range(c_):
            x_c = x_n[c]
            for oh in range(oh_):
                base_h = oh * s - p
                for ow in range(ow_):
                    base_w = ow * s - p
                    best = None
                    tied = False
                    for kh in range(k):
                        ih = base_h + kh
                        if ih < 0 or ih >= h_:
                            continue
                        x_row = x_c[ih]
                        for kw in range(k):
                            iw = base_w + kw
                            if 0 <= iw < w_:
                                v = x_row[iw]
                                if best is None or v > best:
                                    best = v
                                    tied = False
                                elif v == best:
                                    tied = True
                    if tied:
                        raise ValueError(
                            "池化有效窗口存在并列最大值，max 梯度在该点无定义"
                        )


